/* @lc app=leetcode id=3569 lang=kotlin */ class Solution { companion object { val PR: BooleanArray = BooleanArray(100001) { it >= 2 }.also { s -> (2..316).forEach { i -> if (s[i]) (i * i..100000 step i).forEach { s[it] = false } } } } fun add(mx: IntArray, lz: IntArray, o: Int, l: Int, r: Int, a: Int, b: Int, v: Int): Unit = if (a > r || b < l) Unit else if (a <= l && r <= b) mx.set(o, mx[o] + v).also { lz[o] += v } else ((l + r) / 2).let { m -> add(mx, lz, 2 * o, l, m, a, b, v).also { add(mx, lz, 2 * o + 1, m + 1, r, a, b, v) }.also { mx[o] = maxOf(mx[2 * o], mx[2 * o + 1]) + lz[o] } } fun iv(mx: IntArray, lz: IntArray, n: Int, s: java.util.TreeSet<Int>, d: Int) = if (s.size >= 2) add(mx, lz, 1, 1, n - 1, s.first() + 1, s.last(), d) else Unit fun maximumCount(nums: IntArray, queries: Array<IntArray>): IntArray = nums.size.let { n -> PR.let { pr -> IntArray(4 * n).let { mx -> IntArray(4 * n).let { lz -> HashMap<Int, java.util.TreeSet<Int>>().let { pos -> IntArray(1).let { dd -> nums.indices.filter { pr[nums[it]] }.forEach { i -> pos.getOrPut(nums[i]) { java.util.TreeSet() }.add(i) }.let { pos.values.forEach { s -> dd.set(0, dd[0] + 1).let { iv(mx, lz, n, s, 1) } } }.let { queries.map { (idx, v) -> (if (pr[nums[idx]]) pos[nums[idx]]!!.let { s -> iv(mx, lz, n, s, -1).also { s.remove(idx) }.also { if (s.isEmpty()) dd.set(0, dd[0] - 1) else iv(mx, lz, n, s, 1) } } else Unit).let { nums[idx] = v }.let { if (pr[v]) pos.getOrPut(v) { java.util.TreeSet() }.let { s -> (if (s.isEmpty()) dd.set(0, dd[0] + 1) else iv(mx, lz, n, s, -1)).let { s.add(idx) }.let { iv(mx, lz, n, s, 1) } } }.let { dd[0] + mx[1] } }.toIntArray() } } } } } } } }